import java.util.*;

public List<Integer> maximumElement(String[] queries) {
    Deque<Integer> stack = new ArrayDeque<>();
    List<Integer> out = new ArrayList<>();
    for (String q : queries) {
        if (q.charAt(0) == '1') {
            int x = Integer.parseInt(q.split(" ")[1]);
            stack.push(x);
        } else if (q.charAt(0) == '2') {
            stack.pop();
        } else {
            int best = Integer.MIN_VALUE;
            for (int v : stack) {
                best = Math.max(best, v);
            }
            out.add(best);
        }
    }
    return out;
}

