import java.util.*;

public List<Integer> maximumElement(String[] queries) {
    Deque<Integer> main = new ArrayDeque<>();
    Deque<Integer> maxStack = new ArrayDeque<>();
    List<Integer> out = new ArrayList<>();
    for (String q : queries) {
        if (q.charAt(0) == '1') {
            int x = Integer.parseInt(q.substring(2).trim());
            main.push(x);
            int curMax = maxStack.isEmpty() ? x : Math.max(x, maxStack.peek());
            maxStack.push(curMax);
        } else if (q.charAt(0) == '2') {
            main.pop();
            maxStack.pop();
        } else {
            out.add(maxStack.peek());
        }
    }
    return out;
}

