def maximum_element(self, queries: list[str]) -> list[int]:
    main: list[int] = []
    max_stack: list[int] = []
    out: list[int] = []
    for q in queries:
        if q[0] == '1':
            x = int(q.split()[1])
            main.append(x)
            cur_max = x if not max_stack else max(x, max_stack[-1])
            max_stack.append(cur_max)
        elif q[0] == '2':
            main.pop()
            max_stack.pop()
        else:
            out.append(max_stack[-1])
    return out

